from __future__ import annotations

import os

from taf.transport.ssh.connection import SSHConnection, connect  # noqa: F401


class SshConnectionAdapter:
    def __init__(self):
        self._connection = None

    def connect(self, *args, **kwargs) -> None:
        self._connection = connect(*args, **kwargs)  # type: SSHConnection

    def close(self) -> None:
        self._connection.disconnect()

    def execute_command(self, command: str, timeout: int | None = None) -> tuple:
        process = self._connection.send_command(command, timeout=timeout)
        process.join(timeout=timeout)
        stderr = process.read_error().strip()
        stdout = process.read_output().strip()
        rc = process.get_exit_code()
        return stdout, stderr, rc

    def get_file(
        self, source: str, destination: str = ".", timeout: int | None = None
    ) -> list[tuple]:
        """
        Copy a remote file (source) to a local host directory (destination).
        """
        target_is_dir = destination.endswith(os.sep) or destination == "."
        self._create_missing_local_dirs(destination, target_is_dir)

        destination = (
            os.path.join(destination, os.path.basename(source))
            if target_is_dir
            else destination
        )
        self._connection.files.get(source, destination, timeout)
        return [(source, destination)]

    @staticmethod
    def _create_missing_local_dirs(destination: str, target_is_dir: bool) -> None:
        if not target_is_dir:
            destination = os.path.dirname(destination)
        if not os.path.exists(destination):
            os.makedirs(destination)
